// TH16 v1.00a Stage 2 Boss1 (first non-spell).
// Source: st02bs.ecl.txt Boss1:54-79, dependency Boss1_at:81-124.
// Entry state: st02.ecl MainBoss:755-768 creates Boss at (144,-16); Boss:8-52
// movePos(0,128), setHurtbox(40,40), setHitbox(48,48), moveLimit(0,128,280,64).

const TIME_LIMIT: int = 1624;
const OPENING_BUFFER: int = 120;

// Boss() moveLimit(0,128,280,64): full width/height => x +-140, y 96..160.
const LIMIT_X: fx = 140fx;
const LIMIT_Y_LO: fx = 96fx;
const LIMIT_Y_HI: fx = 160fx;
// moveRand(40,4,2.0): fixed direction, speed 2.0*(1-k/40), k=1..40.
const MOVE_FRAMES: int = 40;
const MOVE_SPEED: fx = 2fx;

// Boss1:56 timerReset / :57 setInterrupt is the shell timer; lifeMarker, stars,
// dropSeason, anmPlay/playSound, anmSelect/anmSelectedPlay are UI/presentation.

async sub pattern() {
    wait(OPENING_BUFFER);
    // Boss:14-16/21/26-28: entry position and boxes; real body keeps body collision.
    _ = spawn_enemy(0fx, 128fx, 1000, 0, 0, 0, boss_body);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}

async sub boss_body() {
    set_invuln(65535);
    set_hitbox(24fx);   // source setHitbox(48,48) -> radius 24
    set_hurtbox(20fx);  // source setHurtbox(40,40) -> radius 20

    // diffI(I,20,40,100,120) = Boss1_at:101; wait 20/10/5/3 = :111-120;
    // etSpeed start 1.9/1.9/2.4/2.9 = :89-98.
    var n: int = 120;
    var w: int = 3;
    var sp: fx = 2.9fx;
    if global(GVAR_RANK) == RANK_EASY {
        n = 20; w = 20; sp = 1.9fx;
    } else if global(GVAR_RANK) == RANK_NORMAL {
        n = 40; w = 10; sp = 1.9fx;
    } else if global(GVAR_RANK) == RANK_HARD {
        n = 100; w = 5; sp = 2.4fx;
    }

    wait(60);   // Boss1:63 preface wait

    loop {
        spawn shot_a(n, w, sp);   // Boss1:70 async Boss1_at(0,4,0,30deg,0,2)
        wait(5);                  // Boss1:71
        shot_b(n, w, sp);         // Boss1:72 sync Boss1_at(1,6,0,-20deg,20,2)
        wait(10);                 // Boss1:73
        move_rand_begin();        // Boss1:74 moveRand(40,4,2.0)
        move_wait(50);            // Boss1:75
    }
}

async sub shot_a(n: int, w: int, sp: fx) {
    shot_core(4, n, w, sp, 30deg, 0fx);
}

sub shot_b(n: int, w: int, sp: fx) {
    shot_core(6, n, w, sp, -20deg, 20fx);
}

// Boss1_at:83-124. Emitter is reset per call; the volley loop rewrites the
// polar offset and the two angles before every etOn.
sub shot_core(color: int, n: int, w: int, sp: fx, d: angle, e0: fx) {
    var c: angle = 0deg;
    var e: fx = e0;
    sh_reset(0);
    sh_sprite(0, TH16_KUNAI, color);            // etSprite(id,9,color)
    sh_aim(0, 1);                               // etAim(id,0): aimed fan
    sh_ring(0, 0);                              // fan
    sh_count(0, 7, 1);                          // etCount(id,7,1)
    sh_speed(0, sp, 0fx);                       // etSpeed(start,1.0), 1 layer
    sh_dist(0, 0fx - 4fx * sp);                 // etEx type 2 ANIM a=1: position -= 4*velocity
    // etEx async=1 type 1 SPEEDUP carries no parameters and belongs to the omitted
    // birth-animation stage; configured initial speed already applies.

    for k in 0..n {
        sh_offset_rad(0, c, e);                 // etOffsetRad(id,C,E)
        // etAngle(id, RANDF2*4deg, 30deg + RANDF2*2deg): two independent draws.
        var ra: int = rand(65536);
        var ua: fx = (ra - 32768) as fx / 32768;
        var alpha: int = (728fx * ua) as int;
        var rs: int = rand(65536);
        var us: fx = (rs - 32768) as fx / 32768;
        var delta: int = 5461 + ((364fx * us) as int);
        sh_angle(0, alpha as angle, delta as angle);
        c = c + d;                              // C = C + D
        if e <= 80fx { e = e + 2fx; }           // E = E + 2 while E <= 80
        sh_fire(0);                             // etOn(id)
        wait(w);
    }
}

// moveRand recipe (movement.md): int slot0 = step count, fx0/fx1 = unit vector.
// The attack's waits inside the movement window arm the next source tick.
sub move_rand_begin() {
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    set_self_fx(0, cos(a as angle));
    set_self_fx(1, sin(a as angle));
    set_self_int(0, 0);
    arm_next_step();
}

sub arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < MOVE_FRAMES {
        speed = (((MOVE_FRAMES - k) as fx) * MOVE_SPEED) / (MOVE_FRAMES as fx);
    }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < 0fx - LIMIT_X { nx = 0fx - LIMIT_X; }
    if nx > LIMIT_X { nx = LIMIT_X; }
    if ny < LIMIT_Y_LO { ny = LIMIT_Y_LO; }
    if ny > LIMIT_Y_HI { ny = LIMIT_Y_HI; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub move_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        arm_next_step();
    }
}

